config.query_schema:
query diseaseKnownDrugs($efoId: String!) {
  disease(efoId: $efoId) {
    id
    name
    drugAndClinicalCandidates {
      count
      rows {
        drug {
          id
          name
          maximumClinicalStage
        }
        maxClinicalStage
      }
    }
  }
}

query targetKnownDrugs($ensemblId: String!) {
  target(ensemblId: $ensemblId) {
    id
    approvedSymbol
    drugAndClinicalCandidates {
      count
      rows {
        drug {
          id
          name
          maximumClinicalStage
        }
        maxClinicalStage
        diseases {
          disease {
            id
            name
          }
        }
      }
    }
  }
}

query diseaseAnnotation($efoId: String!) {
  disease(efoId: $efoId) {
    id
    name
    phenotypes {
      rows {
        phenotypeHPO {
          id
          name
          description
          namespace
        }
        phenotypeEFO {
          id
          name
        }
      }
    }
  }
}

query associatedTargets($efoId: String!, $size: Int = 50, $index: Int = 0) {
  disease(efoId: $efoId) {
    id
    name
    associatedTargets(page: {index: $index, size: $size}) {
      count
      rows {
        target {
          id
          approvedSymbol
        }
        score
      }
    }
  }
}

query credibleSetDetail($studyLocusId: String!) {
  credibleSet(studyLocusId: $studyLocusId) {
    studyLocusId
    studyId
    region
    chromosome
    position
    finemappingMethod
    pValueMantissa
    pValueExponent
    beta
    standardError
    confidence
    credibleSetlog10BF
    sampleSize
    variant {
      id
      rsIds
      chromosome
      position
      referenceAllele
      alternateAllele
      mostSevereConsequence {
        id
        label
      }
    }
    study {
      id
      traitFromSource
      publicationFirstAuthor
      publicationTitle
      pubmedId
      nSamples
      diseases {
        id
        name
      }
    }
    l2GPredictions {
      rows {
        target {
          id
          approvedSymbol
        }
        score
      }
    }
  }
}

